import React, { useEffect, useCallback, useMemo, useState } from 'react';
import {
    Table,
    Card,
    Row,
    Col,
    Statistic,
    Tag,
    Input,
    Space,
    Typography,
    Badge,
    Button,
    theme,
    Select,
    Spin
} from 'antd';
import {
    LaptopOutlined,
    ToolOutlined,
    CheckCircleOutlined,
    WarningOutlined,
    SearchOutlined,
    ReloadOutlined,
    EnvironmentOutlined,
    BarcodeOutlined,
    MedicineBoxOutlined
} from '@ant-design/icons';
import useAssetStore from '../../../stores/modules/assetStore';
import useFacilityStore from '../../../stores/facilityStore';
import { TableSkeleton } from '../../shared/Skeleton/Skeleton';
import EmptyState from '../../shared/EmptyState/EmptyState';
import { useResponsive } from '../../../hooks/useResponsive';
import { COMPONENT_WIDTHS } from '../../../styles/tokens';

const { Text, Title } = Typography;

const AssetsListView: React.FC = () => {
    const { token } = theme.useToken();
    const { isMobile, getResponsiveValue } = useResponsive();
    const { availableFacilities, loading: facilitiesLoading } = useFacilityStore();

    // Local state for facility filter
    const [selectedFacilityFilter, setSelectedFacilityFilter] = useState<string[]>([]);

    const {
        assets,
        loading,
        total,
        filters,
        fetchAssets,
        setFilters
    } = useAssetStore();

    const facilityNameById = useMemo(() => {
        return availableFacilities.reduce<Record<string, string>>((acc, facility) => {
            if (facility.hie_id) {
                acc[facility.hie_id] = facility.facility_name;
            }
            return acc;
        }, {});
    }, [availableFacilities]);

    // Determine which facility IDs to use for fetching
    const getFacilityIdsForFetch = useCallback(() => {
        if (selectedFacilityFilter.length > 0) {
            return selectedFacilityFilter;
        }
        // Default to all available facilities
        return availableFacilities.map(f => f.hie_id);
    }, [selectedFacilityFilter, availableFacilities]);

    const handleRefresh = useCallback(() => {
        const facilityIds = getFacilityIdsForFetch();
        fetchAssets(facilityIds);
    }, [fetchAssets, getFacilityIdsForFetch]);

    useEffect(() => {
        handleRefresh();
    }, [handleRefresh, filters.status, filters.page, filters.pageSize, selectedFacilityFilter]);

    const handleFacilityFilterChange = (selectedIds: string[]) => {
        setSelectedFacilityFilter(selectedIds);
    };

    const getStatusColor = (status: string) => {
        switch (status?.toLowerCase()) {
            case 'active': return 'success';
            case 'in maintenance': return 'warning';
            case 'faulty': return 'error';
            case 'retired': return 'default';
            default: return 'processing';
        }
    };

    const columns = [
        {
            title: 'Device Info',
            key: 'device',
            fixed: 'left' as const,
            width: 250,
            render: (record: any) => (
                <Space>
                    <div style={{
                        width: 40,
                        height: 40,
                        borderRadius: 8,
                        background: token.colorFillAlter,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: token.colorPrimary
                    }}>
                        <LaptopOutlined />
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                        <Text strong style={{ fontSize: '14px' }}>{record.device_name || 'Generic Device'}</Text>
                        <Text type="secondary" style={{ fontSize: '12px' }}>
                            <BarcodeOutlined style={{ marginRight: 4 }} /> {record.device_id || record.name}
                        </Text>
                    </div>
                </Space>
            ),
        },
        {
            title: 'Category',
            dataIndex: 'category',
            key: 'category',
            width: 150,
            render: (category: string) => <Tag>{category || 'Automation'}</Tag>
        },
        {
            title: 'Location',
            dataIndex: 'health_facility',
            key: 'facility',
            width: 200,
            render: (facility: string, record: any) => {
                const facilityName =
                    record.facility_name ||
                    record.health_facility_name ||
                    (facility ? facilityNameById[facility] : '') ||
                    facility ||
                    'Unknown Facility';
                const facilityId = record.facility_id || facility || '';

                return (
                    <Space align="start">
                        <EnvironmentOutlined style={{ color: token.colorTextDescription, marginTop: 3 }} />
                        <Space direction="vertical" size={0}>
                            <Text strong style={{ fontSize: '13px' }}>{facilityName}</Text>
                            {facilityId && (
                                <Text type="secondary" style={{ fontSize: '11px' }}>
                                    ID: {facilityId}
                                </Text>
                            )}
                        </Space>
                    </Space>
                );
            }
        },
        {
            title: 'Status',
            dataIndex: 'status',
            key: 'status',
            width: 150,
            render: (status: string) => (
                <Badge status={getStatusColor(status) as any} text={status || 'Active'} />
            )
        },
        {
            title: 'Action',
            key: 'action',
            fixed: 'right' as const,
            width: 100,
            render: () => <Button type="link">View Details</Button>
        }
    ];

    return (
        <div style={{ padding: isMobile ? '16px' : '24px' }}>
            {/* Metric Section */}
            <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
                <Col xs={12} sm={6}>
                    <Card size="small" style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                        <Statistic
                            title={<Text type="secondary" style={{ fontSize: 12 }}>TOTAL ASSETS</Text>}
                            value={assets.length}
                            prefix={<LaptopOutlined style={{ color: token.colorPrimary, marginRight: 8 }} />}
                            valueStyle={{ fontSize: 20, fontWeight: 700 }}
                        />
                    </Card>
                </Col>
                <Col xs={12} sm={6}>
                    <Card size="small" style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                        <Statistic
                            title={<Text type="secondary" style={{ fontSize: 12 }}>ACTIVE</Text>}
                            value={assets.filter(a => a.status === 'Active').length}
                            prefix={<CheckCircleOutlined style={{ color: '#52c41a', marginRight: 8 }} />}
                            valueStyle={{ fontSize: 20, fontWeight: 700 }}
                        />
                    </Card>
                </Col>
                <Col xs={12} sm={6}>
                    <Card size="small" style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                        <Statistic
                            title={<Text type="secondary" style={{ fontSize: 12 }}>MAINTENANCE</Text>}
                            value={assets.filter(a => a.status === 'In Maintenance').length}
                            prefix={<ToolOutlined style={{ color: '#faad14', marginRight: 8 }} />}
                            valueStyle={{ fontSize: 20, fontWeight: 700 }}
                        />
                    </Card>
                </Col>
                <Col xs={12} sm={6}>
                    <Card size="small" style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                        <Statistic
                            title={<Text type="secondary" style={{ fontSize: 12 }}>FAULTY</Text>}
                            value={assets.filter(a => a.status === 'Faulty').length}
                            prefix={<WarningOutlined style={{ color: '#ff4d4f', marginRight: 8 }} />}
                            valueStyle={{ fontSize: 20, fontWeight: 700 }}
                        />
                    </Card>
                </Col>
            </Row>

            {/* Table Section */}
            <Card
                style={{ borderRadius: 12, border: 'none', boxShadow: '0 2px 12px rgba(0,0,0,0.08)' }}
                bodyStyle={{ padding: 0 }}
                title={
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12, padding: '16px 24px' }}>
                        <Title level={4} style={{ margin: 0 }}>Asset Inventory</Title>
                        <Space wrap>
                            <Select
                                mode="multiple"
                                value={selectedFacilityFilter}
                                onChange={handleFacilityFilterChange}
                                placeholder="All Facilities"
                                allowClear
                                loading={facilitiesLoading}
                                style={{
                                    width: getResponsiveValue(COMPONENT_WIDTHS.facilitySelector),
                                    minWidth: isMobile ? '140px' : '200px'
                                }}
                                maxTagCount="responsive"
                                popupMatchSelectWidth={false}
                                notFoundContent={facilitiesLoading ? <Spin size="small" /> : 'No facilities found'}
                                suffixIcon={<EnvironmentOutlined />}
                            >
                                {availableFacilities.map((facility) => (
                                    <Select.Option key={facility.hie_id} value={facility.hie_id}>
                                        <Space>
                                            <MedicineBoxOutlined style={{ fontSize: '12px' }} />
                                            <span>{facility.facility_name}</span>
                                            {facility.facility_mfl && (
                                                <Tag style={{ fontSize: '10px', margin: 0 }}>
                                                    {facility.facility_mfl}
                                                </Tag>
                                            )}
                                        </Space>
                                    </Select.Option>
                                ))}
                            </Select>
                            <Input
                                placeholder="Search by ID or Name..."
                                prefix={<SearchOutlined style={{ color: token.colorTextPlaceholder }} />}
                                style={{
                                    width: getResponsiveValue(COMPONENT_WIDTHS.searchInput),
                                    minWidth: isMobile ? '120px' : 'auto',
                                    borderRadius: 8
                                }}
                                allowClear
                            />
                            <Button icon={<ReloadOutlined />} onClick={handleRefresh} />
                        </Space>
                    </div>
                }
            >
                {loading ? (
                    <TableSkeleton rows={filters.pageSize} />
                ) : assets.length > 0 ? (
                    <Table
                        dataSource={assets}
                        columns={columns}
                        rowKey="name"
                        pagination={{
                            current: filters.page,
                            pageSize: filters.pageSize,
                            total: total,
                            showSizeChanger: true,
                            onChange: (page, pageSize) => setFilters({ page, pageSize })
                        }}
                        scroll={{ x: 'max-content' }}
                        size="middle"
                    />
                ) : (
                    <EmptyState
                        type="no-data"
                        title="No Assets Found"
                        description="Try selecting a different facility or check back later."
                        onAction={handleRefresh}
                        actionText="Reload Assets"
                    />
                )}
            </Card>
        </div>
    );
};

export default AssetsListView;
